(() => {
  let rawRows = [];
  let currentCols = [];
  let lastResultRows = [];

  const dropzone = document.getElementById('duckdb-dropzone');
  const fileInput = document.getElementById('duckdb-file-input');
  const browseBtn = document.getElementById('duckdb-browse-btn');
  const sampleBtn = document.getElementById('duckdb-sample-btn');
  const workbench = document.getElementById('duckdb-workbench');
  const resetBtn = document.getElementById('duckdb-reset-btn');
  const rowsInfo = document.getElementById('duckdb-rows-info');
  const sqlInput = document.getElementById('duckdb-sql-input');
  const runBtn = document.getElementById('duckdb-run-btn');
  const perfBadge = document.getElementById('duckdb-perf-badge');
  const tableHead = document.getElementById('duckdb-table-head');
  const tableBody = document.getElementById('duckdb-table-body');
  const exportCsvBtn = document.getElementById('duckdb-export-csv');
  const exportJsonBtn = document.getElementById('duckdb-export-json');

  const SAMPLE_CSV = `id,product,category,price,units,status
1,Mechanical Gaming Keyboard,Peripherals,129.99,14,In Stock
2,Ultra High Speed HDMI 2.1 Cable,Cables,24.99,48,In Stock
3,4K 120Hz OLED Gaming Monitor,Display,899.99,6,Low Stock
4,Optical 8000Hz Gaming Mouse,Peripherals,79.99,22,In Stock
5,Anti-Drift Hall Effect Sticks,Components,34.99,35,In Stock
6,PCIe Gen4 M.2 NVMe SSD 2TB,Storage,169.99,18,In Stock
7,Noise-Cancelling USB Headset,Audio,99.99,12,In Stock
8,DisplayPort 2.1 Cable 16K,Cables,29.99,40,In Stock
9,Colorimeter Display Calibrator,Tools,199.99,5,Low Stock
10,Wireless Controller Charging Dock,Accessories,39.99,25,In Stock`;

  function parseCsv(text) {
    const lines = text.trim().split(/\r?\n/).filter(l => l.trim().length > 0);
    if (lines.length === 0) return { cols: [], data: [] };

    const cols = lines[0].split(',').map(c => c.trim().replace(/^"|"$/g, ''));
    const data = [];

    for (let i = 1; i < lines.length; i++) {
      const parts = lines[i].split(',').map(c => c.trim().replace(/^"|"$/g, ''));
      const row = {};
      cols.forEach((col, idx) => {
        const val = parts[idx] !== undefined ? parts[idx] : '';
        const num = Number(val);
        row[col] = !isNaN(num) && val !== '' ? num : val;
      });
      data.push(row);
    }
    return { cols, data };
  }

  function loadDataset(csvText) {
    const parsed = parseCsv(csvText);
    currentCols = parsed.cols;
    rawRows = parsed.data;

    rowsInfo.textContent = `${rawRows.length} rows loaded into memory`;
    sqlInput.value = 'SELECT * FROM data LIMIT 10;';
    dropzone.classList.add('hidden');
    workbench.classList.remove('hidden');
    runQuery();
  }

  function runQuery() {
    const q = sqlInput.value.trim().replace(/;$/, '');
    const start = performance.now();
    let working = [...rawRows];

    // Filter
    const whereMatch = q.match(/WHERE\s+([a-zA-Z0-9_]+)\s*(=|>|<|>=|<=|!=)\s*(['"]?)([^'"\s]+)\3/i);
    if (whereMatch) {
      const col = whereMatch[1];
      const op = whereMatch[2];
      const valStr = whereMatch[4];
      const target = !isNaN(Number(valStr)) ? Number(valStr) : valStr;

      working = working.filter(r => {
        const v = r[col];
        if (op === '=') return v === target || String(v).toLowerCase() === String(target).toLowerCase();
        if (op === '!=') return v !== target;
        if (typeof v === 'number' && typeof target === 'number') {
          if (op === '>') return v > target;
          if (op === '<') return v < target;
          if (op === '>=') return v >= target;
          if (op === '<=') return v <= target;
        }
        return true;
      });
    }

    // Order
    const orderMatch = q.match(/ORDER\s+BY\s+([a-zA-Z0-9_]+)(?:\s+(ASC|DESC))?/i);
    if (orderMatch) {
      const col = orderMatch[1];
      const isDesc = orderMatch[2]?.toUpperCase() === 'DESC';
      working.sort((a, b) => {
        const va = a[col];
        const vb = b[col];
        if (typeof va === 'number' && typeof vb === 'number') {
          return isDesc ? vb - va : va - vb;
        }
        return isDesc ? String(vb).localeCompare(String(va)) : String(va).localeCompare(String(vb));
      });
    }

    // Aggregation
    const countMatch = q.match(/SELECT\s+COUNT\(\*\)/i);
    const sumMatch = q.match(/SELECT\s+SUM\(([a-zA-Z0-9_]+)\)/i);

    let colsToRender = [];
    if (countMatch) {
      working = [{ 'count': working.length }];
      colsToRender = ['count'];
    } else if (sumMatch) {
      const col = sumMatch[1];
      const total = working.reduce((acc, r) => acc + (typeof r[col] === 'number' ? r[col] : 0), 0);
      working = [{ [`sum_${col}`]: parseFloat(total.toFixed(2)) }];
      colsToRender = [`sum_${col}`];
    } else {
      // Limit
      const limitMatch = q.match(/LIMIT\s+(\d+)/i);
      if (limitMatch) {
        working = working.slice(0, parseInt(limitMatch[1], 10));
      }
      colsToRender = working.length > 0 ? Object.keys(working[0]) : currentCols;
    }

    const elapsed = (performance.now() - start).toFixed(2);
    perfBadge.textContent = `${working.length} rows (${elapsed} ms)`;
    lastResultRows = working;
    renderTable(colsToRender, working);
  }

  function renderTable(cols, rows) {
    tableHead.innerHTML = `<tr>${cols.map(c => `<th class="px-4 py-3 font-bold">${c}</th>`).join('')}</tr>`;
    if (rows.length === 0) {
      tableBody.innerHTML = `<tr><td colspan="${cols.length}" class="px-4 py-6 text-center text-slate-400 font-sans">No matching records found.</td></tr>`;
      return;
    }
    tableBody.innerHTML = rows.map(r => `
      <tr class="hover:bg-slate-50 transition-colors">
        ${cols.map(c => `<td class="px-4 py-2.5 truncate max-w-xs">${r[c] !== undefined ? r[c] : ''}</td>`).join('')}
      </tr>
    `).join('');
  }

  browseBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    fileInput.click();
  });
  dropzone.addEventListener('click', () => fileInput.click());
  sampleBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    loadDataset(SAMPLE_CSV);
  });

  fileInput.addEventListener('change', () => {
    if (fileInput.files && fileInput.files[0]) {
      const file = fileInput.files[0];
      const reader = new FileReader();
      reader.onload = (e) => loadDataset(e.target.result);
      reader.readAsText(file);
    }
  });

  dropzone.addEventListener('dragover', (e) => e.preventDefault());
  dropzone.addEventListener('drop', (e) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => loadDataset(ev.target.result);
      reader.readAsText(file);
    }
  });

  runBtn.addEventListener('click', runQuery);
  sqlInput.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      runQuery();
    }
  });

  document.querySelectorAll('.sql-preset-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      sqlInput.value = btn.dataset.sql;
      runQuery();
    });
  });

  resetBtn.addEventListener('click', () => {
    workbench.classList.add('hidden');
    dropzone.classList.remove('hidden');
    fileInput.value = '';
  });

  exportCsvBtn.addEventListener('click', () => {
    if (lastResultRows.length === 0) return;
    const cols = Object.keys(lastResultRows[0]);
    const csv = [cols.join(','), ...lastResultRows.map(r => cols.map(c => JSON.stringify(r[c] || '')).join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'query_results.csv';
    a.click();
  });

  exportJsonBtn.addEventListener('click', () => {
    if (lastResultRows.length === 0) return;
    const blob = new Blob([JSON.stringify(lastResultRows, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'query_results.json';
    a.click();
  });
})();
